import sys, platform, unicodedata, stringprep, inspect, hashlib, json, struct
from pathlib import Path
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
names = [name.removeprefix('in_table_') for name in vars(stringprep) if name.startswith('in_table_')]
funcs = [getattr(stringprep, 'in_table_' + name) for name in names]
transitions=[]; previous=None; digest=hashlib.sha256(); mappings={}; checks={}
for point in range(0x110000):
    char=chr(point)
    mask=sum(1<<index for index,func in enumerate(funcs) if func(char))
    digest.update(struct.pack('<I',mask))
    if mask != previous:
        transitions.append([point,mask]); previous=mask
for table in ('b2','b3'):
    function=getattr(stringprep,'map_table_'+table); changed=[]; h=hashlib.sha256()
    for point in range(0x110000):
        mapped=list(map(ord,function(chr(point))))
        h.update(struct.pack('<I',len(mapped)))
        for value in mapped: h.update(struct.pack('<I',value))
        if mapped != [point]: changed.append([point,mapped])
    mappings[table]=changed; checks[table]=h.hexdigest()
source=inspect.getsource(stringprep)
boundaries=sorted({p for start,_ in transitions for p in (start-1,start,start+1) if 0<=p<0x110000}|{0x10ffff})
result={'python':sys.version,'platform':platform.platform(),'unicode':unicodedata.unidata_version,'propertiesUnicode':stringprep.unicodedata.unidata_version,'sourceSHA256':hashlib.sha256(source.encode()).hexdigest(),'tableNames':names,'maskSHA256':digest.hexdigest(),'mappingSHA256':checks,'boundaryCases':[[p,sum(1<<i for i,f in enumerate(funcs) if f(chr(p)))] for p in boundaries],'mappings':mappings,'oracleSource':Path(__file__).read_text()}
Path('packages/safe-python/src/runtime/__snapshots__/stringprep-3.14.7.json').write_text(json.dumps(result,indent=2)+'\n')
Path('/tmp/safe-python-stringprep-data.json').write_text(json.dumps({'transitions':transitions,'mappings':mappings}))
print(json.dumps({'tables':names,'transitions':len(transitions),'boundaries':len(boundaries),'mappings':{k:len(v) for k,v in mappings.items()},'digests':checks}))
